changeSet.sql:
CREATE OR REPLACE FUNCTION clinlims.restart_training_cug_prefix() RETURNS integer
   LANGUAGE plpgsql SECURITY INVOKER SET search_path = pg_catalog, clinlims AS $$
   BEGIN
    IF NOT EXISTS (SELECT 1 FROM clinlims.site_information
                   WHERE name = 'TrainingInstallation' AND lower(trim(value)) = 'true') THEN
     RAISE EXCEPTION 'Public codes may only be reset in a training installation';
    END IF;
    PERFORM id FROM clinlims.sample_cug_counter WHERE id = '1' FOR UPDATE;
    LOCK TABLE clinlims.sample, clinlims.sample_item, clinlims.sample_cug_reservation IN SHARE ROW EXCLUSIVE MODE;
    IF EXISTS (SELECT 1 FROM clinlims.sample) OR EXISTS (SELECT 1 FROM clinlims.sample_item)
       OR EXISTS (SELECT 1 FROM clinlims.sample_cug_reservation) THEN
     RAISE EXCEPTION 'Clear clinical data and CUG reservations before resetting public codes';
    END IF;
    DELETE FROM clinlims.sample_cug_prefix_range;
    DELETE FROM clinlims.sample_cug_prefix;
    UPDATE clinlims.sample_cug_counter SET configured_start = 1, next_candidate = 1,
     last_updated = clock_timestamp() WHERE id = '1';
    ALTER SEQUENCE clinlims.sample_cug_prefix_seq RESTART WITH 1;
    RETURN 1;
   END;
   $$;

